#include <vector>
#include <list>
#include <set>

int main() {
    // 1. Initialize from an array
    int arr[] = { 2, 3, 17, 33, 45, 77 };
    std::set<int> s(arr, arr + sizeof(arr) / sizeof(arr[0]));

    // 2. Initialize a new type from an existing container (conversion occurs)
    std::list<int> l = {10, 20, 30};
    std::vector<float> v(l.begin(), l.end());

    // v now contains {10.0f, 20.0f, 30.0f}
}
